    this.pending = []; this.trace = []; this.maxSteps = maxSteps; this.capsUsed = new Set(); this.stuck = false;
  }
  // a port call: runs `fn` atomically when the scheduler picks it
  port(name, fn, cap) {
    const label = `${taskOf.getStore() || "?"}:${name}`;
    if (cap) this.capsUsed.add(cap);
    return new Promise((resolve, reject) => {
      this.pending.push({ label, exec: () => { try { resolve(fn()); } catch (e) { reject(e); } } });
    });
  }
  note(text) { this.trace.push(`  · ${text}`); }
  // start tasks (each is [label, async fn]) and drive them to completion; `beforeStep(step)` may inject faults
  async drive(tasks, beforeStep) {
    const results = {};
