  const s = collect({ source: `export function f(a) { return { a: a.a, b: a }; }`, origin: "test" });
  const ok = renameParam(s, { entry: "f", from: "a", to: "z" });
  assert.ok(ok.ok);
  assert.equal(instantiate(ok.specimen).f({ a: 1 }).a, 1);
