// guard.mjs — the door in front of any model call. A request is serialised, passed through fold-chat-redact.js
// `deidentify` (the local Python redactor, asked again about the masked text), and only the masked JSON may leave.
// Fails closed: if the redactor cannot be reached or still finds details, `deidentify` throws err.notSent and nothing is
// sent. Provenance never uses the masked text: records refer to specimens by their own sha256 ids (ids here are per-turn).
import { deidentify, createRedactor } from "../../../fold-chat-redact.js";

export function makeGuard({ redactor = createRedactor(), taint = null, extra = [], mode = "default", redact = null } = {}) {
  const spans = redact || ((texts) => redactor.spans(texts));
  const sent = [];
  const guard = async (request) => {
    const out = await deidentify([JSON.stringify(request)], { taint, extra, mode, redact: spans });
    let masked;
    try { masked = JSON.parse(out.texts[0]); } catch { throw Object.assign(new Error("not sent: masking broke the request's JSON"), { notSent: true }); }
    sent.push({ viaRedactor: out.viaRedactor, passes: out.passes, stats: out.deid.stats() });
    return { request: masked, unmask: out.deid.unmask, viaRedactor: out.viaRedactor, passes: out.passes, stats: out.deid.stats() };
  };
  guard.sent = sent;
  return guard;
}

// where did masking change a request? (so an over-masked slot name or obligation id can be shown to the de-id owner)
export function diffMasked(a, b, path = "$") {
  if (typeof a !== typeof b) return [{ path, was: JSON.stringify(a), became: JSON.stringify(b) }];
  if (a && typeof a === "object") { const keys = new Set([...Object.keys(a), ...Object.keys(b || {})]); return [...keys].flatMap((k) => diffMasked(a[k], (b || {})[k], `${path}.${k}`)); }
  return a === b ? [] : [{ path, was: a, became: b }];
}
